param([switch]$Standalone,[switch]$LifecycleOnly)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'editor-cpu.ps1')
$stem=if($Standalone){'terminal11_next'}else{'terminal11_next_setup'}
$sy=[Collections.Generic.Dictionary[string,int]]::new();Get-Content (Join-Path $PSScriptRoot ('..\source\'+$stem+'.sym'))|ForEach-Object{if($_ -match '^[^.]+\.([^:]+): EQU 0x([0-9A-Fa-f]+)'){$sy[$matches[1]]=[Convert]::ToInt32($matches[2],16)}}
$bin=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot ('..\source\'+$stem+'.bin')))
function Assert($v,$s){if(-not $v){throw $s}}
function Word($c,$n,$v){$c.M[$sy[$n]]=[byte]($v-band 255);$c.M[$sy[$n]+1]=[byte]($v-shr 8)}
function W($c,$n){return [BitConverter]::ToUInt16($c.M,$sy[$n])}
function Run($c,$entry){$c.SP=0xF000;$c.EditPtr=-1;$c.Run($entry);$c.ScreenRow=24-$c.M[$(if($c.Lower){23691}else{23689})];$c.ScreenCol=33-$c.M[$(if($c.Lower){23690}else{23688})]}
function Cpu{$c=[TerminalCpu]::new($bin,$sy,30000);$c.StepLimit=20000000;$c.Uart=0;$c.IX=$sy['FLAGS'];$c.ClearScreen();Run $c 'ui_configure';Run $c 'editor_reset';return $c}
function Input($c,[string]$text,[int]$pos=-1){if($pos -lt 0){$pos=$text.Length};$c.Put($sy['Buffer1'],$text);Word $c 'cursor' ($sy['Buffer1']+$pos);Word $c 'text_end' ($sy['Buffer1']+$text.Length)}
function Text($c){return [Text.Encoding]::ASCII.GetString($c.M,$sy['Buffer1'],(W $c 'text_end')-$sy['Buffer1'])}
function Save($c,[string]$text){Input $c $text;$c.M[$sy['Buffer1']+$text.Length]=13;$c.M[$sy['Buffer1']+$text.Length+1]=10;$c.SetHL($sy['Buffer1']+$text.Length+1);$c.A=10;Run $c 'save_last_com'}
function View($c){$p=(W $c 'cursor')-$sy['Buffer1'];$end=(W $c 'text_end')-$sy['Buffer1'];$start=(W $c 'window')-$sy['Buffer1'];Assert ($start -ge 0 -and $p -ge $start -and $p-$start -lt 63) 'Sticky window bounds';for($i=0;$i -lt 63;$i++){$want=if($start+$i -lt $end){$c.M[$sy['Buffer1']+$start+$i]}else{32};if($i -eq $p-$start){$want=$want-bxor 255};for($y=0;$y -lt 8;$y++){$got=$c.M[$c.Pixel((22+[Math]::Floor($i/32)),($i%32))+($y-shl 8)];Assert ($got -eq $want) "Inverse view cell $i/$y expected=$want actual=$got"}}}
$count=0
if(-not $LifecycleOnly){
foreach($len in @(0,1,2,31,32,63,64,255,256)){
 foreach($pos in 0..$len){foreach($op in @('editor_left','editor_right','editor_insert','editor_backspace')){
  $c=Cpu;$c.M[$sy['Buffer1']-1]=165;$c.M[$sy['Buffer1']+259]=90;$text=[Collections.Generic.List[byte]]::new();for($i=0;$i -lt $len;$i++){$text.Add([byte](65+($i%26)));$c.M[$sy['Buffer1']+$i]=$text[$i]};Word $c 'cursor' ($sy['Buffer1']+$pos);Word $c 'text_end' ($sy['Buffer1']+$len);$want=$pos
  switch($op){editor_left{if($pos -gt 0){$want--}}editor_right{if($pos -lt $len){$want++}}editor_insert{if($len -lt 256){$text.Insert($pos,120);$want++}}editor_backspace{if($pos -gt 0){$text.RemoveAt($pos-1);$want--}}}
  $c.A=120;Run $c $op;Assert ((W $c 'cursor') -eq $sy['Buffer1']+$want -and (W $c 'text_end') -eq $sy['Buffer1']+$text.Count) "Editor pointers $op/$len/$pos";for($i=0;$i -lt $text.Count;$i++){Assert ($c.M[$sy['Buffer1']+$i] -eq $text[$i]) "Editor text $op/$len/$pos"};Assert ($c.M[$sy['Buffer1']-1] -eq 165 -and $c.M[$sy['Buffer1']+259] -eq 90 -and $c.SP -eq 0xF000) 'Editor bounds/stack';$count++
 }}
}
foreach($len in @(0,1,31,32,62,63,64,128,255,256)){
 foreach($pos in @(0,[Math]::Floor($len/2),$len)){
  $c=Cpu;Input $c ('X'*$len) $pos;$c.Place(19,5);$c.M[$sy['ui_backup']-1]=165;$c.M[$sy['ui_capacity']+1]=90;Run $c 'ui_show';View $c;Assert ($c.Scrolls -eq 0) 'Unexpected initial scroll';Run $c 'ui_hide';Assert ($c.ScreenRow -eq 19 -and $c.ScreenCol -eq 5) 'Output cursor restore';for($r=22;$r -lt 24;$r++){for($i=0;$i -lt 32;$i++){Assert ($c.M[$c.Pixel($r,$i)] -eq 32) 'Overlay left artifacts'}};Assert ($c.M[$sy['ui_backup']-1] -eq 165 -and $c.M[$sy['ui_capacity']+1] -eq 90) 'UI RAM bounds';$count++
 }
}
foreach($row in @(20,21)){$c=Cpu;Input $c 'AT+GMR';$c.Place($row,7);Run $c 'ui_show';View $c;Assert ($c.Scrolls -eq 0) 'Reserve two rows';Run $c 'ui_hide';Assert ($c.ScreenRow -eq $row -and $c.ScreenCol -eq 7) 'Scrolled output cursor';$count++}
$c=Cpu;Input $c 'AT+FIRST';$c.Place(21,0);Run $c 'ui_show';$scroll=$c.Scrolls;for($i=0;$i -lt 20;$i++){Run $c 'ui_hide';Run $c 'ui_show'};Assert ($c.Scrolls -eq $scroll) 'Repeated display scrolled output';$count++
# Actual history selectors must replace draft without sending or adding scrolls.
$c=Cpu;foreach($t in @('AT','AT+GMR',('L'*256))){Save $c $t};$c.Place(21,0);foreach($expected in @(('L'*256),'AT+GMR','AT')){$c.A=11;Run $c 'revoke_last_command';Run $c 'ui_show';Assert ((Text $c) -eq $expected -and (W $c 'cursor') -eq (W $c 'text_end')) 'History up text/cursor';View $c};Assert ($c.Scrolls -eq 0 -and $c.Tx.Count -eq 0) 'History scroll/send';foreach($expected in @('AT+GMR',('L'*256),'')){$c.A=10;Run $c 'revoke_last_command';Run $c 'ui_show';Assert ((Text $c) -eq $expected) 'History down'};Assert ($c.Scrolls -eq 0) 'History down scroll';$count++
# Enter must send the entire command regardless of cursor, including hidden tail.
foreach($text in @('','AT+GMR',('Z'*256))){$c=Cpu;Input $c $text ([Math]::Floor($text.Length/2));Run $c 'ui_show';Run $c 'do_CRLF';Assert ([Text.Encoding]::ASCII.GetString($c.Tx.ToArray()) -eq $text+"`r`n") 'Enter sent prefix/truncated payload';Assert ((W $c 'text_end') -eq $sy['Buffer1'] -and $c.SP -eq 0xEFFE) 'Send reset/stack';$count++}
$c=Cpu;Input $c 'TEST' 1;$c.A=26;Run $c 'emit_EOT';Assert ([Text.Encoding]::ASCII.GetString($c.Tx.ToArray()) -eq 'TEST'+[char]26+[char]10) 'EOT sent prefix';$count++
# Incoming bytes restore log before output, then overlay returns on idle.
$c=Cpu;Input $c 'DRAFT' 2;$c.Place(19,0);Run $c 'ui_show';foreach($ch in [Text.Encoding]::ASCII.GetBytes("OK`r`n")){$c.Rx.Enqueue($ch);Run $c 'read_rx';Assert ($c.PC -eq $sy['read_key_nc']) 'RX redrew before FIFO drained'};Run $c 'ui_show';View $c;Assert ((Text $c) -eq 'DRAFT' -and (W $c 'cursor') -eq $sy['Buffer1']+2) 'RX lost draft/cursor';Run $c 'ui_hide';Assert ($c.M[$c.Pixel(19,0)] -eq 79 -and $c.M[$c.Pixel(19,1)] -eq 75) 'RX log lost on reserve scroll';$count++
$c=Cpu;Save $c 'AT';Input $c ('P'*128) 40;Run $c 'ui_show';$hist=[Convert]::ToBase64String($c.M[0x7000..0x73ff]);$c.M[$sy['FLAGS']]=64;$c.M[$sy['CURBAUD']]=12;Run $c 'help_screen';Run $c 'ui_show';View $c;Assert ((Text $c) -eq ('P'*128) -and (W $c 'cursor') -eq $sy['Buffer1']+40 -and $c.M[$sy['FLAGS']] -eq 64 -and $hist -eq [Convert]::ToBase64String($c.M[0x7000..0x73ff])) 'Help lost draft/history/mode';$count++
$c=Cpu;foreach($line in $c.Str($sy['Welcome']).Split([char]13)){Assert ($line.Length -le 32) ('Menu width: '+$line)};$count++
# CIPSEND plain text uses the complete line and correct length from the end pointer.
$c=Cpu;Input $c 'AT+MID' 2;$c.M[$sy['FLAGS']]=1;foreach($v in [Text.Encoding]::ASCII.GetBytes("OK`r`n>SEND OK`r`n")){$c.Rx.Enqueue($v)};Run $c 'do_CRLF';$sent=[Text.Encoding]::ASCII.GetString($c.Tx.ToArray());Assert ($sent -eq "AT+CIPSEND=8`r`nAT+MID`r`n") ('CIPSEND full line/length: '+$sent);$count++
# Packed history eviction, including more than 255 entries, through real UI selectors.
$c=Cpu;for($i=0;$i -lt 400;$i++){Save $c ([string]($i%10))};$c.Place(21,0)
for($i=399;$i -ge 59;$i--){$c.A=11;Run $c 'revoke_last_command';Run $c 'ui_show';Assert ((Text $c) -eq [string]($i%10)) 'Packed history up/eviction'}
$c.A=11;Run $c 'revoke_last_command';Assert ((Text $c) -eq '9') 'Oldest boundary changed';for($i=60;$i -le 399;$i++){$c.A=10;Run $c 'revoke_last_command';Assert ((Text $c) -eq [string]($i%10)) 'Packed history down'};$c.A=10;Run $c 'revoke_last_command';Assert ((Text $c) -eq '' -and $c.Scrolls -eq 0) 'Packed history blank/scroll';$count++
foreach($key in @(12,9,8)){$c=Cpu;Input $c 'ABCDE' 2;$c.A=$key;Run $c 'not_set_ansi';$want=if($key -eq 12){1}elseif($key -eq 9){3}else{1};Assert ((W $c 'cursor') -eq $sy['Buffer1']+$want) 'Key dispatch cursor';if($key -eq 8){Assert ((Text $c) -eq 'ACDE') 'Delete did not remove preceding char'}else{Assert ((Text $c) -eq 'ABCDE') 'Arrow deleted text'};$count++}
# Non-uniform pixels and attributes must be restored byte-for-byte.
$c=Cpu;for($y=0;$y -lt 8;$y++){for($x=0;$x -lt 64;$x++){$c.M[0x50C0+($y-shl 8)+$x]=[byte](($x*7+$y)%256)}};for($x=0;$x -lt 64;$x++){$c.M[0x5AC0+$x]=[byte]$x};$before=[Collections.Generic.List[byte]]::new();for($y=0;$y -lt 8;$y++){$before.AddRange([byte[]]$c.M[(0x50C0+($y-shl 8))..(0x50FF+($y-shl 8))])};$before.AddRange([byte[]]$c.M[0x5AC0..0x5AFF]);$c.Place(19,10);Input $c 'EDIT';Run $c 'ui_show';Run $c 'ui_hide';$after=[Collections.Generic.List[byte]]::new();for($y=0;$y -lt 8;$y++){$after.AddRange([byte[]]$c.M[(0x50C0+($y-shl 8))..(0x50FF+($y-shl 8))])};$after.AddRange([byte[]]$c.M[0x5AC0..0x5AFF]);Assert ([Convert]::ToBase64String($before.ToArray()) -eq [Convert]::ToBase64String($after.ToArray())) 'Screen backing pixels/attributes';$count++
foreach($case in @(@('"HELLO"',"HELLO`r`n"),@('123,"ABC"',("{"+"ABC`r`n")),@(('Z'*256),(('Z'*256)+"`r`n")))){$c=Cpu;Input $c $case[0] 1;$c.M[$sy['FLAGS']]=1;foreach($v in [Text.Encoding]::ASCII.GetBytes("OK`r`n>SEND OK`r`n")){$c.Rx.Enqueue($v)};Run $c 'do_CRLF';$expected='AT+CIPSEND='+$case[1].Length+"`r`n"+$case[1];Assert ([Text.Encoding]::ASCII.GetString($c.Tx.ToArray()) -ceq $expected) ('CIPSEND structured/full payload: '+$case[0]);$count++}
}
# Cursor movement changes only old/new glyph pixels: no ROM repaint or blank frame.
foreach($case in @(@('ABCDE',2,12),@(('L'*256),256,12),@('ABCDE',0,12),@('ABCDE',5,9))){$c=Cpu;Input $c $case[0] $case[1];Run $c 'ui_show';$before=[byte[]]$c.M[0x4000..0x5AFF];$printed=$c.Printed.Count;$back=[Convert]::ToBase64String($c.M[0x6C00..0x6E3F]);$c.A=$case[2];Run $c 'not_set_ansi';$diff=0;for($i=0;$i -lt $before.Length;$i++){if($before[$i] -ne $c.M[0x4000+$i]){$diff++}};$want=if(($case[1] -eq 0 -and $case[2] -eq 12)-or($case[1] -eq $case[0].Length -and $case[2] -eq 9)){0}else{16};Assert ($diff -eq $want -and $c.Printed.Count -eq $printed+8 -and $back -eq [Convert]::ToBase64String($c.M[0x6C00..0x6E3F])) 'Arrow flicker/full redraw';View $c;$count++}
# Cross the viewport edge; repaint view only, without restoring the screen backing.
$c=Cpu;Input $c ('Q'*256) 256;Run $c 'ui_show';Word $c 'cursor' ((W $c 'window'));$c.A=12;Run $c 'not_set_ansi';View $c;Assert ($c.M[$sy['ui_visible']] -eq 1 -and $c.Scrolls -eq 0) 'Viewport edge scrolled/hid editor';$count++
# Confirmed history deletion is non-blocking and preserves the draft.
$c=Cpu;Save $c 'AT';Save $c 'AT+GMR';Input $c 'DRAFT' 2;Run $c 'ui_show';$hist=[Convert]::ToBase64String($c.M[0x7000..0x73FF]);$c.A=199;Run $c 'check_history_confirm';Run $c 'ui_show';Assert ($c.M[$sy['history_confirm']] -eq 1 -and [Text.Encoding]::ASCII.GetString($c.Printed.ToArray()).Contains('DELETE COMMAND HISTORY? (Y/N)')) 'History confirmation prompt';$c.A=120;Run $c 'check_history_confirm';Assert ($c.M[$sy['history_confirm']] -eq 1 -and (Text $c) -eq 'DRAFT') 'Unrelated key confirmed/edited draft';$c.Rx.Enqueue(79);Run $c 'read_rx';Assert ($c.Rx.Count -eq 0 -and $c.M[$sy['history_confirm']] -eq 1) 'Confirmation blocked UART';$c.A=110;Run $c 'check_history_confirm';Assert ($hist -eq [Convert]::ToBase64String($c.M[0x7000..0x73FF]) -and $c.M[$sy['history_confirm']] -eq 0) 'N erased history';$c.A=199;Run $c 'check_history_confirm';$c.A=121;Run $c 'check_history_confirm';Assert ([BitConverter]::ToUInt16($c.M,0x7000) -eq 0 -and (W $c 'history_pos') -eq 0 -and $c.M[$sy['history_confirm']] -eq 0 -and (Text $c) -eq 'DRAFT' -and (W $c 'cursor') -eq $sy['Buffer1']+2) 'Y deletion/draft';$c.A=11;Run $c 'revoke_last_command';Assert ((Text $c) -eq 'DRAFT') 'Cleared history recalled old text';$count++
# ATE0 echo survives editor restore and a complete no-echo response.
$c=Cpu;Input $c 'ATE0';$c.Place(19,0);Run $c 'ui_show';Run $c 'do_CRLF';Run $c 'ui_show';foreach($ch in [Text.Encoding]::ASCII.GetBytes("`r`nOK`r`n")){$c.Rx.Enqueue($ch);Run $c 'read_rx'};Run $c 'ui_show';Run $c 'ui_hide';for($i=0;$i -lt 4;$i++){Assert ($c.M[$c.Pixel(19,$i)] -eq [int][char]('ATE0'[$i])) 'ATE0 first letter/output overwritten'};$count++
# A low ROM counter must not stop startup or repeated help.
$c=Cpu;$c.M[23692]=1;$c.Run('start1');Assert ($c.PC -eq $sy['read_key']) 'Startup did not reach editor';$c.Run('ui_show');for($i=0;$i -lt 4;$i++){$c.Resume=$true;$c.Run('help_screen')};Assert ($c.PC -eq $sy['read_key']) 'Help blocked on scroll?';$count++
# A continuously arriving RX stream must not exhaust the counter at 255 lines.
$c=Cpu;$c.Place(21,0);$c.M[23692]=1;for($i=0;$i -lt 700;$i++){$c.Rx.Enqueue(13);Run $c 'read_rx'};Assert ($c.Scrolls -ge 699 -and $c.M[23692] -gt 0) 'Continuous RX blocked on scroll?';$count++
# SS+W clears the entire draft at any cursor position; never sends or erases history.
foreach($len in @(0,1,63,128,256)){foreach($pos in @(0,[Math]::Floor($len/2),$len)){$c=Cpu;Save $c 'AT';Save $c 'AT+GMR';$c.A=11;Run $c 'revoke_last_command';Input $c ('X'*$len) $pos;Run $c 'ui_show';$h=[Convert]::ToBase64String($c.M[0x7000..0x73FF]);$c.A=200;Run $c 'check_history_confirm';Run $c 'ui_show';Assert ((Text $c) -eq '' -and (W $c 'cursor') -eq $sy['Buffer1'] -and (W $c 'window') -eq $sy['Buffer1'] -and (W $c 'history_pos') -eq 0) 'SS+W did not clear draft state';Assert ($h -eq [Convert]::ToBase64String($c.M[0x7000..0x73FF]) -and $c.Tx.Count -eq 0) 'SS+W sent data/erased history';View $c;$c.A=11;Run $c 'revoke_last_command';Assert ((Text $c) -eq 'AT+GMR') 'History unavailable after SS+W';$count++}}
# SS+E restores the UART default from all supported rates without losing the draft.
foreach($speed in 0..14){$c=Cpu;Save $c 'AT';Input $c 'DRAFT' 2;$c.M[$sy['CURBAUD']]=$speed;Run $c 'ui_show';$history=[Convert]::ToBase64String($c.M[0x7000..0x73FF]);$c.A=201;Run $c 'check_history_confirm';Assert ($c.M[$sy['CURBAUD']] -eq 0 -and $c.Prescaler -eq 243 -and (Text $c) -eq 'DRAFT' -and (W $c 'cursor') -eq $sy['Buffer1']+2 -and $c.Tx.Count -eq 0 -and $history -eq [Convert]::ToBase64String($c.M[0x7000..0x73FF])) 'SS+E default/draft/history';$count++}
# One real invocation: retain the original return/IX/placeholder stack across commands.
$c=Cpu;$c.IX=0x5678;$c.Run('start1');$liveSP=$c.SP;Assert ($liveSP -eq 0xEFFA -and (W $c 'cursor') -eq $sy['Buffer1'] -and (W $c 'text_end') -eq $sy['Buffer1']) 'Startup editor/stack'
for($i=0;$i -lt 12;$i++){Input $c ('AT+'+$i) 1;$c.Run('ui_show');$c.Resume=$true;$c.Run('do_CRLF');Assert ($c.SP -eq $liveSP) 'Repeated Enter leaked stack';$c.A=11;$c.Resume=$true;$c.Run('revoke_last_command');Assert ($c.SP -eq $liveSP) 'History leaked stack';$c.Resume=$true;$c.Run('help_screen');Assert ($c.SP -eq $liveSP) 'Help leaked stack'}
$c.Run('ui_show');$c.Resume=$true;$c.Run('finish');Assert ($c.SP -eq 0xF000 -and $c.IX -eq 0x5678 -and $c.M[$sy['ui_visible']] -eq 0) 'Exit did not restore stack/IX/screen';$count++
# A single Y/N must acknowledge visibly, close the modal state and allow editing.
foreach($key in @(89,121,78,110,6)){$c=Cpu;Save $c 'AT';Input $c 'DRAFT' 2;$c.A=199;Run $c 'check_history_confirm';Run $c 'ui_show';$printed=$c.Printed.Count;$c.A=$key;Run $c 'check_history_confirm';Assert ($c.M[$sy['history_confirm']] -eq 0) 'Answer still waiting for Enter';$answer=[Text.Encoding]::ASCII.GetString($c.Printed.GetRange($printed,$c.Printed.Count-$printed).ToArray());$expected=if($key -eq 6){"`r"}else{[string][char]$key+"`r"};Assert ($answer -ceq $expected) 'Answer lacks immediate visible acknowledgement';Assert (([BitConverter]::ToUInt16($c.M,0x7000) -eq 0) -eq ($key -in @(89,121))) 'Wrong immediate history action';$c.A=88;Run $c 'check_history_confirm';Assert ((Text $c) -eq 'DRXAFT') 'Editor not ready immediately after answer';$count++}
# Decode the real two-key matrix; SS+ENTER must not collide with TRUE VIDEO.
$c=Cpu;$c.KeysSS=252;Run $c 'inkey';Assert ($c.A -eq 6) 'SS+SPACE matrix code';$count++
$c=Cpu;$c.KeysSS=253;$c.KeysEnter=254;Run $c 'inkey';$expected=202;Assert ($c.A -eq $expected) 'SS+ENTER matrix code';$count++
$c=Cpu;$c.KeysCS=254;$c.KeysNumbers=251;Run $c 'inkey';Assert ($c.A -eq 3) 'TRUE VIDEO matrix code';$count++
# Both exit paths must restore the caller; ON must not touch the power ports.
$exitKeys=@(6);foreach($key in $exitKeys){$c=Cpu;$c.IX=0x5678;$c.Run('start1');$c.Run('ui_show');$power=$c.Power;$writes=$c.OutPorts.Count;$printed=$c.Printed.Count;$c.A=$key;$c.Resume=$true;$c.Run('check_exit');Assert ($c.SP -eq 0xF000 -and $c.IX -eq 0x5678 -and $c.M[$sy['ui_visible']] -eq 0) 'Exit stack/IX/editor';$ports=@($c.OutPorts.GetRange($writes,$c.OutPorts.Count-$writes));$msg=[Text.Encoding]::ASCII.GetString($c.Printed.GetRange($printed,$c.Printed.Count-$printed).ToArray());if($Standalone -and $key -eq 202){Assert (($c.Power -band 1) -eq 0 -and $ports -contains 0x703B -and $ports -contains 0x713B -and $msg.Contains('WiFi turned OFF. Bye.')) 'OFF exit did not power down/message'}else{Assert ($c.Power -eq $power -and $ports -notcontains 0x703B -and $ports -notcontains 0x713B) 'ON exit touched power';if($Standalone){Assert ($msg.Contains('WiFi is ON')) 'ON exit missing status'}};$count++}
"PASS: $count integrated editor scenarios ($stem); assembled Z80 with modelled ROM/UART."